@pytest.mark.regression
def test_api_1_list_users(api_client) -> None:
    """List users

    ID: API-1 | Source: users.json

    Expected:
      - Status code 200 and response contains fields id, name, email within 500 ms
    """
    # Step 1: Send GET request to /api/users
